              "sub": "Kulturstaatsminister Wolfram Weimer hat heute anlässlich der Eröffnung des neuen „Zentrums Welterbe“ den Naumburger Dom besucht. In seinem Grußwort betonte Staatsminister Weimer: „Das ‚Zentrum Welterbe‘ ist eine wichtige Ergänzung für den Naumburger Dom. Es macht die kulturhistorische Bedeutung eines Bauwerks zugänglich, dessen Strahlkraft weit über die Grenzen Sachsen-Anhalts hinausreicht. Die grandiose Architektur des Doms und die schöpferische Symbiose von Kunst und Handwerk überwältigen mich geradezu. Dieser Dom ist gespeicherte Geschichte, gebaute Identität. Mit seiner herausragenden mittelalterlichen Bau- und Bildhauerkunst steht er beispielhaft für die Innovationskraft und den Gestaltungswillen unserer frühen Vorfahren. Auf diesen Mut zur Innovation können wir stolz sein. Diese Innovationskraft gehört zu unserer kulturellen DNA. Das 1.000-jährige Bestehen des Doms im Jahr 2028 bietet die große Chance, seine überragende Bedeutung international sichtbarer zu machen.“ Staatsm..."
