              "sub": "Kulturstaatsminister Wolfram Weimer besuchte heute mit Rainer Robra, Staatsminister und Minister für Kultur des Landes Sachsen-Anhalt, Schloss Mosigkau im Gartenreich Dessau-Wörlitz. Gemeinsam überreichten sie einen symbolischen Förderbescheid über rund 5,1 Millionen Euro für die Sanierung des Westlichen Kavalierhauses des Schlossensembles. Staatsminister Weimer: „Schloss Mosigkau ist ein einzigartiger Ort und eines der letzten weitgehend erhaltenen Rokokoensembles Mitteldeutschlands. Hier erleben wir Geschichte zum Anfassen und können in die höfische Kultur des 18. Jahrhunderts eintauchen. Die nahezu vollständig erhaltene barocke Gemäldehängung im Galeriesaal mit Werken flämischer und holländischer Meister macht Schloss Mosigkau zu einem Ort von großer kunst- und kulturgeschichtlicher Bedeutung. Mit der gemeinsamen Förderung leisten Bund und Land einen wichtigen Beitrag zum Erhalt für künftige Generationen.“ Der Bund stellt für die Sanierung des Westlichen Kavalierhauses von Sch..."
